def maximum_pair_sum_by_largest_digit(nums):
    best_by_digit={};answer=-1
    for value in nums:
        digit=max(str(value))
        if digit in best_by_digit:answer=max(answer,value+best_by_digit[digit])
        best_by_digit[digit]=max(value,best_by_digit.get(digit,0))
    return answer

